// Normalizes a user-entered URL into a valid href. Users routinely type
// "compass.com" or "www.compass.com" without a scheme -- browsers treat a
// scheme-less href as a RELATIVE path (e.g. sds.janienation.com/compass.com),
// so the link silently goes nowhere. This prepends https:// when there's no
// scheme already. mailto:/tel: and existing http(s) links are left alone.
function ensureHref(url) {
  if (!url) return "";
  const u = String(url).trim();
  if (!u) return "";
  if (/^(https?:|mailto:|tel:)/i.test(u)) return u;
  return "https://" + u.replace(/^\/+/, "");
}

// Builds an href for a text element's optional link, based on which link
// type the person picked in the panel (website/email/phone). This is what
// lets someone just type "jane@compass.com" or "804 555 1234" without
// needing to know to type mailto:/tel: themselves -- the scheme is applied
// here based on the selected type instead of guessed from the input.
function buildLinkHref(linkType, value) {
  if (!value) return "";
  const v = String(value).trim();
  if (!v) return "";
  if (linkType === "email") return /^mailto:/i.test(v) ? v : "mailto:" + v;
  if (linkType === "phone") return /^tel:/i.test(v) ? v : "tel:" + v.replace(/[^\d+]/g, "");
  return ensureHref(v);
}

function interpolate(text, profile) {
  if (!text) return "";
  // Convert (R) shorthand to registered trademark symbol
  text = text.replace(/\(R\)/g, "®").replace(/\(r\)/g, "®");
  return text
    .replace(/\{\{name\}\}/g, profile.name || "Your Name")
    .replace(/\{\{title\}\}/g, profile.title || "Realtor®")
    .replace(/\{\{company\}\}/g, profile.company || "Compass")
    .replace(/\{\{phone\}\}/g, profile.phone || "(555) 000-0000")
    .replace(/\{\{mobile\}\}/g, profile.mobile || "(555) 000-0000")
    .replace(/\{\{email\}\}/g, profile.email || "you@compass.com")
    .replace(/\{\{website\}\}/g, profile.website || "compass.com")
    .replace(/\{\{address\}\}/g, profile.address || "123 Main St, City, State")
    .replace(/\{\{bio\}\}/g, profile.bio || "");
}

